// Lifecycle values shared by the client and the server.
// The database schema must use exactly these strings so no translation layer is needed.

export const SUBSCRIBER_STATUSES = ["active", "suspended", "disconnected"] as const;
export type SubscriberStatus = (typeof SUBSCRIBER_STATUSES)[number];

// The invoice lifecycle, in the order an invoice normally moves through it.
// A voided invoice is terminal: it stays in the database forever and is reversed
// by a credit ledger entry, never deleted.
//
//   draft          → generated by the billing job, not yet posted to the ledger
//   posted         → ledger debit created; the subscriber owes the amount
//   partially_paid → some payment applied, a balance still remains
//   paid           → fully settled
//   overdue        → past the due date and not fully paid
//   void           → reversed by a credit entry; the row is retained
//
// The database enum must use exactly these strings so no translation layer is needed.
export const INVOICE_STATUSES = [
  "draft",
  "posted",
  "partially_paid",
  "paid",
  "overdue",
  "void",
] as const;
export type InvoiceStatus = (typeof INVOICE_STATUSES)[number];

/** Human-readable status names, used in badges and filters. */
export const INVOICE_STATUS_LABELS = {
  draft: "Draft",
  posted: "Posted",
  partially_paid: "Partially Paid",
  paid: "Paid",
  overdue: "Overdue",
  void: "Void",
} as const satisfies Record<InvoiceStatus, string>;

// What kind of obligation an invoice represents.
export const INVOICE_TYPES = [
  "monthly_subscription", // Regular monthly bill generated by the billing job
  "reconnection_fee", // Charged when a suspended account is reconnected
  "adjustment", // Manual correction, with a justification in notes
  "late_fee", // Penalty for an overdue account
] as const;
export type InvoiceType = (typeof INVOICE_TYPES)[number];

/** Human-readable invoice type names, used in the invoice detail header. */
export const INVOICE_TYPE_LABELS = {
  monthly_subscription: "Monthly Subscription",
  reconnection_fee: "Reconnection Fee",
  adjustment: "Adjustment",
  late_fee: "Late Fee",
} as const satisfies Record<InvoiceType, string>;

export const PAYMENT_METHODS = ["cash", "gcash", "bank_transfer", "check"] as const;
export type PaymentMethod = (typeof PAYMENT_METHODS)[number];

export const COLLECTION_BATCH_STATUSES = ["open", "remitted", "reconciled"] as const;
export type CollectionBatchStatus = (typeof COLLECTION_BATCH_STATUSES)[number];